/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: release, key, candidate, group, view, applied, summary, mount, ready, expectSteps, appendItem,
 *              appendTracklist, appendResponse, rowsSection, rowItems
 *   Constants: uploads
 * Tests
 *   - rows that need no answer are folded, while values from file tags, an artist mismatch and Luna suggestions are flagged outside the fold
 *   - Publish stays unavailable while the server says it waits or needs answers, a placeholder-only credit says so at once, and otherwise it opens the confirmation
 *   - a lookup conflict only in MusicBrainz IDs is headed as one and shows each side's IDs beside the names
 *   - a conflict with the administrator's value offers Keep mine or Use lookup value bound to the saved value, and an append shows Album values as not applied
 *   - Luna label and Disc Number suggestions arrive as ticked rows of their own, and an append marks the label not applied
 *   - a tie lists the values that differ with each release's barcode, catalogue number, country and medium, and allows one release or none
 *   - the only next-step button is a free retry while lookup is busy, unavailable or stopped, the name box is next when nothing matches, and the secondary paid Luna AI button follows the lookup controls in every lookup state
 *   - the retry and the Luna AI button act only on request, and the Luna AI button opens its paid confirmation with the project and daily budget
 *   - the Draft section's Luna AI button opens the same confirmation and starts nothing until it is confirmed
 *   - the paid Luna AI button follows the conflict answers, the values to check and a tie, and precedes the Luna AI suggestions
 *   - while lookup is queued or running the paid Luna AI button stays enabled and starts Luna AI only through its confirmation, without touching the lookup
 *   - the paid Luna AI button is absent until the summary read succeeds, and where this server cannot run lookup no run offers the retry
 *   - Luna suggestions arrive with the server's ticks: unticking is kept for the confirmation, a conflict cannot be ticked, and applying now accepts ticked and rejects unticked ones
 *   - the name box accepts names and an optional Artist only, keeps no history and is not listener Search, and a folder-name run shows that name for editing
 *   - visibility defaults to public and changes in place as one field save
 *   - the summary polls while a lookup is queued, running or retrying, and a newer read refreshes the page's project
 *   - a lookup refusal shows its own message and reads the project and its summary again
 *   - Publish is not offered before the summary read settles or after it fails, nor once the publication is locked, which also fixes visibility and, like a pending cleanup, disables Luna AI
 *   - the status names an unconfigured, replaced or none-applied lookup and counts stale files, and the Luna AI button needs analysis access, budget and an idle analysis
 *   - answered conflicts fold with their answer, an artist mismatch is flagged only for a preselection applied in this run, and neither unsaved nor appended Album values are flagged as file tags
 *   - a suggestion whose value an unsaved change writes cannot be ticked, and the fold lists the shown tracks in approved order with decisions, cover and upload progress
 *   - the fold marks a cover chosen automatically, never an explicit one, and an append marks it not applied
 *   - Publish waits while the applied release's cover is being staged, the summary polls meanwhile, and a staged lookup cover is named in the fold
 *   - the Luna AI confirmation focuses Cancel, closes on Escape without starting anything, and cannot be confirmed while its budget is loading, failed or too small for one more run
 *   - the iTunes stage has its own status and next step: searching iTunes, retrying it, unavailable after no match, MusicBrainz unavailable never as no match, and an applied iTunes-only result, checked or not
 *   - values resting on an applied iTunes-only result are flagged as iTunes only, and as not checked against MusicBrainz, and never folded
 *   - an append flags only the track values an applied iTunes-only result wrote, an unsaved change is not flagged, and a choice of none flags nothing
 *   - an append to an Album with an expected tracklist lists the row each appended file of the shown draft fills with its flags, and the flags never hold Publish
 *   - numbering from the expected tracklist sends one field save of the saved values, is disabled with other saves, a locked publication or a read of another revision, and is absent without a proposal
 *   - an append without an expected tracklist, and an import that is no append, show no expected rows
 *   - a file without a Disc Number on a tracklist of several discs, and one at a position no row has, say so beside the row they reach
 *   - numbering is disabled while the summary was read at another automatic-write revision, since automation may have changed the values it numbers
 * @end-catalog */

import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
