test('the paid Luna AI button follows the conflict answers, the values to check and a tie, and precedes the Luna AI suggestions', async () => {
  const follows = (first: Element, second: Element) => Boolean(first.compareDocumentPosition(second) & Node.DOCUMENT_POSITION_FOLLOWING);
  const item = detail(); item.draft.album.label = labelEntry('Mine'); item.automaticPaths = ['album.releaseDate'];
  const conflicts = [{ path: 'album.label', slotId: null, lookup: labelEntry('Lookup Label'), answer: null }];
  const { section } = mount(item, lookupResponse({ lookup: view({ candidates: [candidate(1)], groups: [group(1, 'Synthetic Album')], applied: applied({ conflicts }), needsAnswer: { tie: false, conflicts: ['album.label'] } }),
    summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }] }) }));
  const luna = await within(section()).findByRole('button', { name: 'Use Luna AI (paid)' }), answers = within(section()).getAllByRole('button', { name: /^(Keep mine|Use lookup value)$/ });
  expect(answers).toHaveLength(2);
  await expectSteps(section(), ['Use Luna AI (paid)'], { chooser: true });
  for (const control of [...answers, within(section()).getByRole('list', { name: 'Values to check' })]) expect(follows(control, luna), control.textContent ?? '').toBe(true);
  // The suggestions Luna AI returned come after the button that starts it.
  expect(follows(luna, within(section()).getByRole('group', { name: 'Luna AI suggestions' }))).toBe(true);
  cleanup();
  // A tie is answered with the lookup controls; Luna AI stays a secondary choice after them.
  const tied = mount(detail(), lookupResponse({ lookup: view({ candidates: [candidate(1), candidate(2)], groups: [group(1, 'Synthetic Album'), group(2, 'Synthetic Album (Deluxe)')], needsAnswer: { tie: true, conflicts: [] } }) }));
  const tie = await within(tied.section()).findByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  await expectSteps(tied.section(), ['Use Luna AI (paid)'], { chooser: true });
  expect(follows(tie, within(tied.section()).getByRole('button', { name: 'Use Luna AI (paid)' }))).toBe(true);
});

