test('Publish is not offered before the summary read settles or after it fails, nor once the publication is locked, which also fixes visibility and, like a pending cleanup, disables Luna AI', async () => {
  const read = deferred<Response>();
  let rendered = mount(detail(), () => read.promise);
  expect(within(rendered.section()).getByRole('status')).toHaveTextContent('Loading…');
  expect(screen.queryByRole('button', { name: 'Review and approve publishing' })).not.toBeInTheDocument();
  read.resolve(json(lookupResponse())); expect(await ready()).toBeEnabled();
  cleanup();
  rendered = mount(detail(), async () => json({ code: 'unavailable' }, 503));
  expect(await within(rendered.section()).findByText('The request could not be confirmed. Your saved draft is retained.')).toHaveAttribute('role', 'status');
  expect(screen.queryByRole('button', { name: 'Review and approve publishing' })).not.toBeInTheDocument();
  // The server refuses Luna AI under a locked publication or a cancelled approval whose cleanup is pending, so its button is
  // disabled there even beside an applied release; once cleanup ends it can start again.
  const appliedRelease = lookupResponse({ lookup: view({ candidates: [candidate(1)], groups: [group(1, 'Synthetic Album')], applied: applied() }) });
  const recovery = (cleanupPending: boolean) => ({ operationId: '30000000-0000-4000-8000-000000000001', cleanupPending, startedByMe: true });
  for (const publication of ['preparing', 'needsAttention', 'complete'] as const) {
    cleanup(); const item = detail(); item.publication = publication; mount(item, appliedRelease);
    expect(await screen.findByRole('combobox', { name: 'Visibility' })).toBeDisabled();
    expect(screen.queryByRole('button', { name: 'Review and approve publishing' })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Use Luna AI (paid)' }), publication).toBeDisabled();
  }
  for (const cleanupPending of [true, false]) {
    cleanup(); const item = detail(); item.publication = 'cancelled'; item.publicationRecovery = recovery(cleanupPending); mount(item, appliedRelease);
    await ready();
    expect(screen.getByRole('button', { name: 'Use Luna AI (paid)' }).hasAttribute('disabled'), String(cleanupPending)).toBe(cleanupPending);
  }
  // A summary disabled by the page (unsaved edits, a conflict or running analysis) offers no write of its own.
  cleanup();
  const conflicts = [{ path: 'album.label', slotId: null, lookup: labelEntry('Lookup Label'), answer: null }], item = detail(); item.draft.album.label = labelEntry('Mine');
  mount(item, lookupResponse({ lookup: view({ state: 'stopped', outcome: null, issue: 'permissionLost', candidates: [candidate(1)], applied: applied({ conflicts }), needsAnswer: { tie: false, conflicts: ['album.label'] } }),
    summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }] }) }), { disabled: true });
  expect(await screen.findByRole('combobox', { name: 'Visibility' })).toBeDisabled();
  for (const name of ['Retry lookup', 'Use Luna AI (paid)', 'Keep mine', 'Use lookup value', 'Apply ticked suggestions now']) expect(screen.getByRole('button', { name })).toBeDisabled();
  expect(screen.getByRole('checkbox', { name: /^Title/ })).toBeDisabled();
  for (const name of ['Name', 'Artist (optional)']) expect(within(screen.getByRole('group', { name: 'Look up by name' })).getByRole('textbox', { name })).toBeDisabled();
  // Publish includes unsaved edits, so only its own gate holds it.
  cleanup(); mount(detail(), lookupResponse(), { disabled: true });
  expect(await ready()).toBeEnabled();
});

