test('a suggestion whose value an unsaved change writes cannot be ticked, and the fold lists the shown tracks in approved order with decisions, cover and upload progress', async () => {
  const item = detail(); item.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }];
  item.selectedCoverSlotId = 'cover'; item.upload = { ready: 1, total: 2, available: true };
  const draft = { ...item.draft, tracks: [{ ...item.draft.tracks[0], title: 'Second Song', trackNumber: 2 }, { ...item.draft.tracks[1], title: 'First Song', trackNumber: 1 }] };
  const changes = [{ path: `tracks.${slotId}.trackNumber`, base: null, value: 2 }];
  mount(item, lookupResponse({ summary: summary({ luna: [{ id: 'c'.repeat(24), tick: 'ticked' }, { id: 'd'.repeat(24), tick: 'ticked' }] }) }),
    { approval: { draft, changes }, uploads: { ...uploads, running: true } });
  const luna = await screen.findByRole('group', { name: 'Luna AI suggestions' });
  const number = within(luna).getByRole<HTMLInputElement>('checkbox', { name: /^Track 1 · Track number: 2 → 1/ });
  expect([number.checked, number.disabled, within(luna).getByRole<HTMLInputElement>('checkbox', { name: /^Title/ }).checked]).toEqual([false, true, true]);
  expect(within(luna).getByText('This value changed after Luna AI ran. Edit the draft manually or keep its current value.')).toBeInTheDocument();
  const fold = screen.getByText('Values that need no answer').closest('details')!;
  expect(within(within(fold).getByText('Disc and track order').closest('div')!).getAllByRole('listitem').map(entry => entry.textContent))
    .toEqual(['Disc 1 · Track 1 · First Song', 'Disc 1 · Track 2 · Second Song']);
  for (const text of ['Manually selected cover', 'Saved decisions: 1. The publication confirmation lists each new or reused record.', '1 of 2 files confirmed · Uploading'])
    expect(within(fold).getByText(text)).toBeInTheDocument();
  // The read is keyed by the saved revision and automatic writes, so a newer project reads its summary again.
  const access = { viewerId: viewer, epoch: 0, generation: 1 };
  expect(importSummaryQuery(access, { ...item, revision: 2 }).queryKey).not.toEqual(importSummaryQuery(access, item).queryKey);
  expect(importSummaryQuery(access, { ...item, valueRevision: 1 }).queryKey).not.toEqual(importSummaryQuery(access, item).queryKey);
});

test('the fold marks a cover chosen automatically, never an explicit one, and an append marks it not applied', async () => {
  const item = detail(), embedded = `embedded-${slotId}`; item.coverChoice = 'automatic'; item.selectedCoverSlotId = embedded;
  item.assets = [{ slotId: embedded, state: 'ready', byteLength: 100, sha256: 'a'.repeat(64), contentType: 'image/png', tags: null, recovery: null }];
  const cover = () => within(screen.getByText('Values that need no answer').closest('details')!).getByText('Album cover', { selector: 'dt' }).nextElementSibling!;
  mount(item); await ready(); expect(cover()).toHaveTextContent(/^Private cover candidate · Chosen automatically$/); cleanup();
  mount({ ...item, coverChoice: 'explicit' }); await ready(); expect(cover()).toHaveTextContent(/^Private cover candidate$/); cleanup();
  mount(item, lookupResponse({ summary: summary({ append: true }) })); await ready(); expect(cover()).toHaveTextContent(/^Private cover candidate · Chosen automatically · Not applied$/); cleanup();
  // No image shared and nothing chosen: No cover selected, without the mark.
  mount({ ...item, selectedCoverSlotId: null }); await ready(); expect(cover()).toHaveTextContent(/^No cover selected$/);
});

test('Publish waits while the applied release\'s cover is being staged, the summary polls meanwhile, and a staged lookup cover is named in the fold', async () => {
  const waitingCover = { uploads: false, lookup: false, cover: true, analysis: false };
  let rendered = mount(detail(), lookupResponse({ summary: summary({ waiting: waitingCover }) }));
  expect(await ready()).toBeDisabled();
  expect(within(rendered.section()).getByText('Publish waits while the applied release’s cover is being staged.')).toHaveAttribute('role', 'status');
  cleanup();
  // Once staging ended (staged, failed or skipped), the server stops waiting and so does Publish.
  rendered = mount(detail(), lookupResponse({ summary: summary({ waiting: { ...waitingCover, cover: false } }) }));
  expect(await ready()).toBeEnabled(); expect(screen.queryByText(/cover is being staged/)).not.toBeInTheDocument();
  cleanup();
  const access = { viewerId: viewer, epoch: 0, generation: 1 }, interval = (cover: boolean, online = true, state: string | null = null) =>
    importSummaryQuery(access, detail(), online).refetchInterval({ state: { data: lookupResponse({ lookup: state ? view({ state }) : null, summary: summary({ waiting: { ...waitingCover, cover } }) }) as never } });
  expect([interval(true), interval(true, false), interval(false), interval(true, true, 'complete'), interval(true, true, 'retrying')]).toEqual([3000, false, false, 3000, 10_000]);
  const lookupSlot = 'lookup-musicbrainz:0000000b-0000-4000-8000-000000000001', item = detail();
  item.coverChoice = 'automatic'; item.selectedCoverSlotId = lookupSlot;
  item.assets = [{ slotId: lookupSlot, state: 'ready', byteLength: 100, sha256: 'a'.repeat(64), contentType: 'image/jpeg', tags: null, recovery: null }];
  mount(item); await ready();
  expect(within(screen.getByText('Values that need no answer').closest('details')!).getByText('Album cover', { selector: 'dt' }).nextElementSibling!)
    .toHaveTextContent(/^Cover Art Archive front artwork · 0000000b · Chosen automatically$/);
});

test('the Luna AI confirmation focuses Cancel, closes on Escape without starting anything, and cannot be confirmed while its budget is loading, failed or too small for one more run', async () => {
  const confirm = (response: () => Promise<Response>) => {
    vi.stubGlobal('fetch', vi.fn(response));
    const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
    const onConfirm = vi.fn(), onClose = vi.fn();
    render(<QueryClientProvider client={client}><ImportAnalysisConfirmation item={detail()} disabled={false} onConfirm={onConfirm} onClose={onClose} /></QueryClientProvider>);
    return { onConfirm, onClose, dialog: screen.getByRole('dialog', { name: 'Use Luna AI? This is a paid AI service' }), start: () => screen.getByRole('button', { name: 'Start paid Luna AI' }) };
  };
  const read = deferred<Response>();
  let opened = confirm(() => read.promise);
  await waitFor(() => expect(within(opened.dialog).getByRole('button', { name: 'Cancel' })).toHaveFocus());
  expect(within(opened.dialog).getByRole('status')).toHaveTextContent('Loading…'); expect(opened.start()).toBeDisabled();
  fireEvent.keyDown(document, { key: 'Escape' });
  expect(opened.onClose).toHaveBeenCalledOnce(); expect(opened.onConfirm).not.toHaveBeenCalled();
  cleanup();
  opened = confirm(async () => json({ code: 'unavailable' }, 503));
  expect(await within(opened.dialog).findByText('The request could not be confirmed. Your saved draft is retained.')).toBeInTheDocument();
  expect(opened.start()).toBeDisabled();
  // The fixture's two files need two calls: one for the Album and one per ten files.
  for (const [analysis, enabled] of [[{ runs: 0, attempts: 20, daily: 200 }, false], [{ runs: 1, attempts: 1, daily: 200 }, false], [{ runs: 1, attempts: 20, daily: 1 }, false], [{ runs: 1, attempts: 2, daily: 2 }, true]] as const) {
    cleanup(); opened = confirm(async () => json(lookupResponse({ summary: summary({ analysis }) })));
    await within(opened.dialog).findByText(`Left today for all imports: ${analysis.daily} paid Luna AI calls.`);
    expect(opened.start().hasAttribute('disabled'), JSON.stringify(analysis)).toBe(!enabled);
  }
  fireEvent.click(opened.start()); expect(opened.onConfirm).toHaveBeenCalledOnce();
});

test('the iTunes stage has its own status and next step: searching iTunes, retrying it, unavailable after no match, MusicBrainz unavailable never as no match, and an applied iTunes-only result, checked or not', async () => {
  const itunesKey = 'itunes:1689358563', itunes = candidate(1, { key: itunesKey, releaseId: '1689358563', source: 'itunes', label: null, catalogNumber: null, country: null, formats: [] });
  const appliedItunes = (notChecked: boolean) => applied({ candidateKey: itunesKey, releaseId: '1689358563', source: 'itunes', notChecked });
  const luna = ['Use Luna AI (paid)'], retry = ['Retry lookup', 'Use Luna AI (paid)'];
  const cases: [Record<string, unknown>, string, string[]][] = [
    // The stage also runs after MusicBrainz stayed unavailable, so its status claims no MusicBrainz answer.
    [{ state: 'running', outcome: null, itunes: 'running' }, 'Looking up metadata in the iTunes Search API…', luna],
    [{ state: 'retrying', outcome: null, issue: 'sourceBusy', itunes: 'retrying' }, 'The iTunes Search API is busy or unavailable, so lookup retries automatically. You can retry now at no cost.', retry],
    // MusicBrainz is still retried as before while the stage has not started.
    [{ state: 'retrying', outcome: null, issue: 'sourceBusy', itunes: 'notQueried' }, 'MusicBrainz is busy or unavailable, so lookup retries automatically. You can retry now at no cost.', retry],
    // Nothing matched, so the name box is the next step, as for any run that found no matching release.
    [{ outcome: 'noRelease', itunes: 'unavailable' }, 'MusicBrainz found no matching release, and the iTunes Search API was unavailable. Try another name, or use Luna AI (paid).', luna],
    [{ candidates: [candidate(2, { status: 'notMatching', groupKey: null })], itunes: 'unavailable' },
      'MusicBrainz found no matching release, and the iTunes Search API was unavailable. Try another name, or use Luna AI (paid).', luna],
    // MusicBrainz stayed unavailable (the completed run keeps its issue): never no match, whatever iTunes answered.
    [{ candidates: [candidate(2, { status: 'incomplete', groupKey: null, comparison: null })], issue: 'sourceUnavailable', itunes: 'unavailable' },
      'Release details could not be fetched, so no match was confirmed. Retry the lookup at no cost, or use Luna AI (paid).', retry],
    [{ candidates: [{ ...itunes, status: 'notMatching', groupKey: null, notChecked: true }], issue: 'sourceUnavailable', itunes: 'answered' },
      'Metadata lookup is unavailable. Retry the lookup at no cost, or use Luna AI (paid).', retry],
    [{ outcome: 'noRelease', issue: 'sourceBusy', itunes: 'answered' }, 'Metadata lookup is unavailable. Retry the lookup at no cost, or use Luna AI (paid).', retry],
    [{ candidates: [itunes], groups: [group(1, 'Synthetic Album')], applied: appliedItunes(false), itunes: 'answered' },
      'Applied an iTunes-only result: Synthetic Album 1. MusicBrainz found no release for it, so its values are flagged.', luna],
    [{ candidates: [itunes], groups: [group(1, 'Synthetic Album')], applied: appliedItunes(true), issue: 'sourceUnavailable', itunes: 'answered' },
      'Applied an iTunes-only result: Synthetic Album 1. It was not checked against MusicBrainz, so its values are flagged.', retry]
  ];
  for (const [lookup, status, steps] of cases) {
    const { section } = mount(detail(), lookupResponse({ lookup: view(lookup), summary: summary() }));
    expect(await within(section()).findByText(status, { selector: 'p' })).toHaveAttribute('role', 'status');
    await expectSteps(section(), steps, { chooser: lookup.state === undefined && Boolean((lookup.candidates as unknown[] | undefined)?.length) });
    cleanup();
  }
});

test('values resting on an applied iTunes-only result are flagged as iTunes only, and as not checked against MusicBrainz, and never folded', async () => {
  const itunesKey = 'itunes:1689358563', item = detail();
  item.draft.album.title = 'iTunes Title'; item.draft.album.artists = [artistEntry('Synthetic Ensemble')]; item.draft.tracks[0].title = 'iTunes Song';
  item.automaticPaths = ['album.title', 'album.artists', `tracks.${slotId}.title`]; item.lookupPaths = ['album.title', 'album.artists', `tracks.${slotId}.title`];
  const lookup = view({ candidates: [candidate(1, { key: itunesKey, releaseId: '1689358563', source: 'itunes', notChecked: true })], groups: [group(1, 'iTunes Title')],
    applied: applied({ candidateKey: itunesKey, releaseId: '1689358563', source: 'itunes', notChecked: true }), itunes: 'answered' });
  const { section } = mount(item, lookupResponse({ lookup, summary: summary() }));
  await ready();
  const flagged = within(section()).getByRole('list', { name: 'Values to check' });
  expect(within(flagged).getAllByRole('listitem').map(row => row.textContent)).toEqual([
    'Title: iTunes Title · iTunes only · Not checked against MusicBrainz', 'Artists: Synthetic Ensemble · iTunes only · Not checked against MusicBrainz',
    'Track 1 · Title: iTunes Song · iTunes only · Not checked against MusicBrainz']);
  const fold = within(section()).getByText('Values that need no answer').closest('details')!;
  expect([within(fold).queryByText('iTunes Title'), within(fold).queryByText('Synthetic Ensemble · Primary')]).toEqual([null, null]);
  cleanup();
  // A checked iTunes-only result is flagged as iTunes only; a MusicBrainz release's values are folded as before.
  mount(item, lookupResponse({ lookup: { ...lookup, applied: applied({ candidateKey: itunesKey, releaseId: '1689358563', source: 'itunes', notChecked: false }) }, summary: summary() }));
  await ready();
  expect(within(screen.getByRole('list', { name: 'Values to check' })).getAllByRole('listitem')[0].textContent).toBe('Title: iTunes Title · iTunes only');
});

test('an append flags only the track values an applied iTunes-only result wrote, an unsaved change is not flagged, and a choice of none flags nothing', async () => {
  const itunesKey = 'itunes:1689358563', item = detail();
  item.draft.album.title = 'iTunes Title'; item.draft.tracks[0].title = 'iTunes Song';
  item.automaticPaths = ['album.title', `tracks.${slotId}.title`]; item.lookupPaths = ['album.title', `tracks.${slotId}.title`];
  const lookup = (choice: 'chosen' | 'none') => view({ candidates: [candidate(1, { key: itunesKey, releaseId: '1689358563', source: 'itunes', notChecked: false })], groups: [group(1, 'iTunes Title')],
    applied: applied({ candidateKey: choice === 'none' ? null : itunesKey, releaseId: choice === 'none' ? null : '1689358563', choice, basis: choice === 'none' ? null : 'chosen', source: 'itunes' }), itunes: 'answered' });
  // An append applies no Album value, so only the track title is flagged as resting on the iTunes-only result.
  mount(item, lookupResponse({ lookup: lookup('chosen'), summary: summary({ append: true }) }));
  await ready();
  expect(within(screen.getByRole('list', { name: 'Values to check' })).getAllByRole('listitem').map(row => row.textContent)).toEqual(['Track 1 · Title: iTunes Song · iTunes only']);
  cleanup();
  // A value the administrator is changing now is theirs, not the result's.
  mount(item, lookupResponse({ lookup: lookup('chosen'), summary: summary() }), { approval: { draft: item.draft, changes: [{ path: `tracks.${slotId}.title`, base: 'iTunes Song', value: 'Mine' }] } });
  await ready();
  expect(within(screen.getByRole('list', { name: 'Values to check' })).getAllByRole('listitem').map(row => row.textContent)).toEqual(['Title: iTunes Title · iTunes only']);
  cleanup();
  // None applied: nothing rests on the result any more.
  mount(item, lookupResponse({ lookup: lookup('none'), summary: summary() }));
  await ready();
  expect(screen.queryByRole('list', { name: 'Values to check' })).toBeNull();
});

/** A saved append to an Album whose expected tracklist has a filled opening, a one-second second row and a third row without a duration. */
function appendItem() {
  const item = detail();
  item.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: 'a'.repeat(24), candidateRevision: 'r-album' }];
  item.draft.tracks = [{ slotId, title: 'First Song', discNumber: null, trackNumber: 2 }, { slotId: slotTwo, title: '', discNumber: null, trackNumber: null }];
  return item;
}
const appendTracklist = (extra: Record<string, unknown> = {}) => ({ albumId: 'a'.repeat(24), durationToleranceMs: 3000,
  rows: [{ discNumber: 1, trackNumber: 1, title: 'Opening', durationMs: null, filled: true }, { discNumber: 1, trackNumber: 2, title: 'Second Row', durationMs: 1000, filled: false },
    { discNumber: 1, trackNumber: 3, title: 'Third Row', durationMs: null, filled: false }],
  files: [{ slotId, durationMs: 100_000, durationPrecisionMs: 0, appended: true }, { slotId: slotTwo, durationMs: null, durationPrecisionMs: 0, appended: true }], numbering: [], ...extra });
const appendResponse = (tracklist: unknown = appendTracklist(), revision = 1) => lookupResponse({ revision, summary: summary({ append: true, appendTracklist: tracklist }) });
const rowsSection = () => screen.findByRole('region', { name: 'Album\'s expected tracklist' });
const rowItems = (section: HTMLElement) => within(section).getAllByRole('listitem').map(item => item.textContent);

test('an append to an Album with an expected tracklist lists the row each appended file of the shown draft fills with its flags, and the flags never hold Publish', async () => {
  const item = appendItem();
  let rendered = mount(item, appendResponse());
  const section = await rowsSection();
  expect(within(section).getByText('These files fill 1 of the Album\'s 2 missing-file rows.')).toBeInTheDocument();
  expect(rowItems(section)).toEqual(['Disc 1 · Track 2 · First Song · Row Disc 1 · Track 2: Second Row · Duration differs from the row\'s by more than 3 seconds',
    'Disc 1 · Track — · 02 Second.mp3 · No row · No Track Number']);
  // The rows stay outside the fold, before the paid Luna AI button, and Publish stays available.
  expect(section.closest('details')).toBeNull();
  expect(section.compareDocumentPosition(within(rendered.section()).getByRole('button', { name: 'Use Luna AI (paid)' })) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  expect(await ready()).toBeEnabled();
  cleanup();
  // An unsaved number change moves its file onto a row, since Publish includes it.
  const draft = { ...item.draft, tracks: [item.draft.tracks[0], { ...item.draft.tracks[1], trackNumber: 3 }] };
  rendered = mount(item, appendResponse(), { approval: { draft, changes: [{ path: `tracks.${slotTwo}.trackNumber`, base: null, value: 3 }] } });
  expect(rowItems(await rowsSection())).toEqual(['Disc 1 · Track 2 · First Song · Row Disc 1 · Track 2: Second Row · Duration differs from the row\'s by more than 3 seconds',
    'Disc 1 · Track 3 · 02 Second.mp3 · Row Disc 1 · Track 3: Third Row']);
  expect(screen.getByText('These files fill 2 of the Album\'s 2 missing-file rows.')).toBeInTheDocument();
  cleanup();
  // Reused and skipped files are not appended, so they are not listed; a file on a row a member fills says it already has a file.
  mount(item, appendResponse(appendTracklist({ files: [{ slotId, durationMs: 1000, durationPrecisionMs: 0, appended: false }, { slotId: slotTwo, durationMs: null, durationPrecisionMs: 0, appended: true }] })),
    { approval: { draft: { ...item.draft, tracks: [item.draft.tracks[0], { ...item.draft.tracks[1], trackNumber: 1 }] }, changes: [{ path: `tracks.${slotTwo}.trackNumber`, base: null, value: 1 }] } });
  expect(rowItems(await rowsSection())).toEqual(['Disc 1 · Track 1 · 02 Second.mp3 · Row Disc 1 · Track 1: Opening · This row already has a file']);
  expect(await ready()).toBeEnabled();
});

test('numbering from the expected tracklist sends one field save of the saved values, is disabled with other saves, a locked publication or a read of another revision, and is absent without a proposal', async () => {
  const item = appendItem(), numbering = [{ slotId: slotTwo, discNumber: 1, trackNumber: 3, title: 'Third Row' }];
  const button = async () => within(await rowsSection()).getByRole('button', { name: 'Number from the Album\'s expected tracklist' });
  // The shown draft's unsaved change is not the base: the save is made against the saved draft the server proposed it for.
  const draft = { ...item.draft, tracks: [item.draft.tracks[0], { ...item.draft.tracks[1], title: 'Unsaved' }] };
  const { run } = mount(item, appendResponse(appendTracklist({ numbering })), { approval: { draft, changes: [{ path: `tracks.${slotTwo}.title`, base: '', value: 'Unsaved' }] } });
  const action = await button();
  expect(action).not.toHaveClass(styles.primary);
  expect(action).toHaveAccessibleDescription('Files without your own Disc and Track Numbers take the only row each one can fill, with its title when the file\'s title is empty or automatic.');
  fireEvent.click(action);
  expect(run).toHaveBeenCalledWith(`/${item.id}`, 'PATCH', { expectedRevision: 1, changes: [{ path: `tracks.${slotTwo}.discNumber`, base: null, value: 1 },
    { path: `tracks.${slotTwo}.trackNumber`, base: null, value: 3 }, { path: `tracks.${slotTwo}.title`, base: '', value: 'Third Row' }] });
  cleanup();
  mount(item, appendResponse(appendTracklist({ numbering })), { disabled: true }); expect(await button()).toBeDisabled(); cleanup();
  mount({ ...item, publication: 'preparing' }, appendResponse(appendTracklist({ numbering }))); expect(await button()).toBeDisabled(); cleanup();
  mount(item, appendResponse(appendTracklist({ numbering }), 0)); expect(await button()).toBeDisabled(); cleanup();
  mount(item, appendResponse(appendTracklist())); await rowsSection();
  expect(screen.queryByRole('button', { name: 'Number from the Album\'s expected tracklist' })).not.toBeInTheDocument();
});

test('an append without an expected tracklist, and an import that is no append, show no expected rows', async () => {
  mount(appendItem(), appendResponse(null)); await ready();
  expect(screen.queryByText('Album\'s expected tracklist')).not.toBeInTheDocument(); cleanup();
  mount(detail(), lookupResponse({ revision: 1, summary: summary({ append: false, appendTracklist: appendTracklist() }) })); await ready();
  expect(screen.queryByText('Album\'s expected tracklist')).not.toBeInTheDocument();
});

test('a file without a Disc Number on a tracklist of several discs, and one at a position no row has, say so beside the row they reach', async () => {
  const item = appendItem();
  item.draft.tracks = [{ slotId, title: 'First Song', discNumber: null, trackNumber: 1 }, { slotId: slotTwo, title: 'Second Song', discNumber: 2, trackNumber: 9 }];
  mount(item, appendResponse(appendTracklist({ rows: [{ discNumber: 1, trackNumber: 1, title: 'Opening', durationMs: null, filled: false },
    { discNumber: 2, trackNumber: 1, title: 'Disc Two Opening', durationMs: null, filled: false }] })));
  const section = await rowsSection();
  expect(rowItems(section)).toEqual(['Disc 1 · Track 1 · First Song · Row Disc 1 · Track 1: Opening · No Disc Number, and the expected tracklist has several discs',
    'Disc 2 · Track 9 · Second Song · No row · Not in the expected tracklist']);
  expect(within(section).getByText('These files fill 1 of the Album\'s 2 missing-file rows.')).toBeInTheDocument();
  expect(await ready()).toBeEnabled();
});

test('numbering is disabled while the summary was read at another automatic-write revision, since automation may have changed the values it numbers', async () => {
  const numbering = [{ slotId: slotTwo, discNumber: 1, trackNumber: 3, title: 'Third Row' }], item = appendItem();
  const read = (valueRevision: number) => lookupResponse({ revision: item.revision, valueRevision, summary: summary({ append: true, appendTracklist: appendTracklist({ numbering }) }) });
  const button = async () => within(await rowsSection()).getByRole('button', { name: 'Number from the Album\'s expected tracklist' });
  mount(item, read(item.valueRevision + 1)); expect(await button()).toBeDisabled(); cleanup();
  const { run } = mount(item, read(item.valueRevision)), action = await button();
  expect(action).toBeEnabled(); fireEvent.click(action);
  expect(run).toHaveBeenCalledTimes(1);
});
